import{_ as i}from"./chunks/projects.BdG50VF9.js";import{_ as s,c as a,o as r,a2 as t}from"./chunks/framework.CIiVzG-O.js";const v=JSON.parse('{"title":"Avant de valider","description":"Relisez chaque fichier modifié dans un dossier de projet et validez sans quitter qDiff.","frontmatter":{"title":"Avant de valider","description":"Relisez chaque fichier modifié dans un dossier de projet et validez sans quitter qDiff."},"headers":[],"relativePath":"fr/guide/projects.md","filePath":"fr/guide/projects.md","lastUpdated":1794296122000}'),o={name:"fr/guide/projects.md"};function n(u,e,d,l,c,p){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="avant-de-valider" tabindex="-1">Avant de valider <a class="header-anchor" href="#avant-de-valider" aria-label="Permalink to &quot;Avant de valider&quot;">​</a></h1><p>Un rapide « qu&#39;est-ce que j&#39;ai vraiment changé ? » vaut la peine avant chaque validation. Ouvrez un dossier de projet dans qDiff et la réponse est déjà sous vos yeux.</p><img src="'+i+'" alt="Une liste de fichiers modifiés à côté d&#39;une comparaison codée par couleur" class="guide-shot"><h2 id="ouvrir-un-dossier-de-projet" tabindex="-1">Ouvrir un dossier de projet <a class="header-anchor" href="#ouvrir-un-dossier-de-projet" aria-label="Permalink to &quot;Ouvrir un dossier de projet&quot;">​</a></h2><p>Choisissez le dossier d&#39;un projet Git depuis <strong>Fichier → Ouvrir</strong>, ou déposez-le sur la fenêtre. qDiff réunit les fichiers que vous avez touchés dans une seule liste.</p><h2 id="lire-la-liste-puis-les-modifications" tabindex="-1">Lire la liste, puis les modifications <a class="header-anchor" href="#lire-la-liste-puis-les-modifications" aria-label="Permalink to &quot;Lire la liste, puis les modifications&quot;">​</a></h2><p>Chaque fichier est marqué selon ce qui lui est arrivé : nouveau, modifié ou supprimé. Cliquez sur l&#39;un d&#39;eux et le panneau de droite montre exactement ce qui a changé à l&#39;intérieur, avec les mêmes couleurs et les mêmes surlignages au niveau des mots que dans une comparaison de fichiers classique.</p><p>Parcourez-les un par un — la liste conserve votre position, si bien que rien n&#39;est oublié lors d&#39;une longue revue.</p><h2 id="terminer-dans-la-meme-fenetre" tabindex="-1">Terminer dans la même fenêtre <a class="header-anchor" href="#terminer-dans-la-meme-fenetre" aria-label="Permalink to &quot;Terminer dans la même fenêtre&quot;">​</a></h2><p>Quand tout vous semble correct, validez depuis ici. Vous pouvez aussi mettre à jour, pousser, annuler ou résoudre un conflit sans quitter la comparaison. Aucune autre application n&#39;a besoin d&#39;être ouverte, et aucun compte n&#39;est requis.</p><div class="tip custom-block"><p class="custom-block-title">Ce n&#39;est pas un dossier de projet ?</p><p>Tout dossier ordinaire s&#39;ouvre quand même comme une comparaison de dossiers classique — <a href="./folders.html">comparez des dossiers</a> fonctionne partout.</p></div><p>Ensuite : <a href="./more.html">images, archives et autres</a>.</p>',12)])])}const h=s(o,[["render",n]]);export{v as __pageData,h as default};
